marshal:
if value, ok := containerInfo.Value(); ok {
	x.ContainerInfo = value
}

if x.Type != MapObjectTypeEntity && x.Type != MapObjectTypeBlock {
	r.UnknownEnumOption(x.Type, "map tracked object type")
}

if variant >= uint32(len(typeNames)) {
	r.UnknownEnumOption(variant, "scoreboard entry variant")
	return
}

if err := x.validate(); err != nil {
	r.InvalidValue(fmt.Sprintf("Skin %v", x.SkinID), "serialised skin", err.Error())
}

if value, ok := stackNetworkID.Value(); ok {
	x.StackNetworkID = value
}

if x.DurabilityCorrection < -32768 || x.DurabilityCorrection > 32767 {
	r.InvalidValue(x.DurabilityCorrection, "durability correction", "must fit in an int16")
}
